export interface Workshop { id: number; title: string; roomCode: string; }
export interface WorkshopRow { key: string; label: string; room: string; }
export interface WorkshopFilter { text: string; room: string | null; }
export type WorkshopLoader = () => Promise<readonly Workshop[]>;
export type WorkshopMapper = (workshop: Workshop) => WorkshopRow;
export type AddWorkshopDialog = () => Promise<boolean>;
export type ErrorReporter = (error: unknown) => void;

export class WorkshopToolbar {
  private rows: WorkshopRow[] = [];
  private readonly listeners: Array<(filter: WorkshopFilter) => void> = [];

  constructor(
    private readonly loader: WorkshopLoader,
    private readonly mapper: WorkshopMapper,
    private readonly dialog: AddWorkshopDialog,
    private readonly reportError: ErrorReporter,
  ) {}

  subscribe(listener: (filter: WorkshopFilter) => void): () => void {
    this.listeners.push(listener);
    let active = true;
    return () => {
      if (!active) return;
      active = false;
      const index = this.listeners.indexOf(listener);
      if (index >= 0) this.listeners.splice(index, 1);
    };
  }

  emitFilter(filter: WorkshopFilter): void {
    for (const listener of [...this.listeners]) listener({ ...filter });
  }

  getRows(): WorkshopRow[] {
    return this.rows.map(row => ({ ...row }));
  }

  async initialize(): Promise<boolean> {
    try {
      const workshops = await this.loader();
      const next = workshops.map(workshop => ({ ...this.mapper({ ...workshop }) }));
      this.rows = next;
      return true;
    } catch (error) {
      this.reportError(error);
      return false;
    }
  }

  async openAddDialog(): Promise<boolean> {
    try {
      if (!(await this.dialog())) return false;
    } catch (error) {
      this.reportError(error);
      return false;
    }
    if (!(await this.initialize())) return false;
    this.emitFilter({ text: "", room: null });
    return true;
  }
}
